package ru.local.glasshome;
import android.content.*;import android.content.pm.*;import android.graphics.*;import android.graphics.drawable.*;import android.os.*;import android.text.*;import android.view.*;import android.widget.*;import java.util.*;import java.util.concurrent.*;
/** Lazy application catalogue and recycled, asynchronously rendered library tiles. */
final class Library {
 final Home home;final ExecutorService worker=Executors.newSingleThreadExecutor(r->new Thread(()->{android.os.Process.setThreadPriority(android.os.Process.THREAD_PRIORITY_BACKGROUND);r.run();},"LiquidLibrary"));
 final android.util.LruCache<String,Bitmap> images=new android.util.LruCache<>(96);
 final Map<String,List<Runnable>> waiting=new HashMap<>();final List<Runnable> catalogueCallbacks=new ArrayList<>();
 volatile List<Item> items=Collections.emptyList();volatile long loadedAt;boolean loading,closed;
 static final class Item{final ResolveInfo app;final String name,key,search;Item(Home h,ResolveInfo app){this.app=app;name=app.loadLabel(h.getPackageManager()).toString();key=app.activityInfo.packageName+"/"+app.activityInfo.name;search=name.toLowerCase(Locale.ROOT);}}
 Library(Home home){this.home=home;}
 synchronized List<Item> loadBlocking(){if(loadedAt>0&&SystemClock.uptimeMillis()-loadedAt<300000)return items;Intent intent=new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER);ArrayList<Item> found=new ArrayList<>();for(ResolveInfo app:home.getPackageManager().queryIntentActivities(intent,0))if(!app.activityInfo.packageName.equals(home.getPackageName()))try{found.add(new Item(home,app));}catch(Exception ignored){}found.sort((a,b)->a.name.compareToIgnoreCase(b.name));items=Collections.unmodifiableList(found);loadedAt=SystemClock.uptimeMillis();return items;}
 void loadAsync(Runnable done){if(closed)return;if(loadedAt>0&&SystemClock.uptimeMillis()-loadedAt<300000){if(done!=null)done.run();return;}if(done!=null)catalogueCallbacks.add(done);if(loading)return;loading=true;worker.execute(()->{try{loadBlocking();}catch(Exception ignored){}finally{home.handler.post(()->{loading=false;if(closed)return;ArrayList<Runnable> callbacks=new ArrayList<>(catalogueCallbacks);catalogueCallbacks.clear();for(Runnable callback:callbacks)callback.run();});}});}
 ArrayList<ResolveInfo> copyApps(){ArrayList<ResolveInfo> apps=new ArrayList<>();for(Item item:loadBlocking())apps.add(item.app);return apps;}
 String imageKey(Item item){return item.key+":"+home.palette+":"+home.prefs.getBoolean("miuiIcons",false)+":"+home.prefs.getBoolean("colorIcons",false)+":"+(int)home.dp(57);}
 void request(Item item,String key,Runnable ready){if(closed)return;List<Runnable> callbacks=waiting.get(key);if(callbacks!=null){callbacks.add(ready);return;}callbacks=new ArrayList<>();callbacks.add(ready);waiting.put(key,callbacks);worker.execute(()->{try{int side=(int)home.dp(57);Bitmap bitmap=Bitmap.createBitmap(side,side,Bitmap.Config.ARGB_8888);home.appIcon(new Canvas(bitmap),item.app.loadIcon(home.getPackageManager()),item.app.activityInfo.packageName,new RectF(0,0,side,side));images.put(key,bitmap);}catch(Exception ignored){}home.handler.post(()->{List<Runnable> complete=waiting.remove(key);if(!closed&&complete!=null)for(Runnable callback:complete)callback.run();});});}
 void close(){closed=true;worker.shutdownNow();waiting.clear();catalogueCallbacks.clear();}
 void show(){Home h=home;h.drawer=true;Home.Sheet root=h.new Sheet();root.setBackground(new BitmapDrawable(h.getResources(),h.bg(h.getResources().getDisplayMetrics().widthPixels,h.getResources().getDisplayMetrics().heightPixels)));View tint=new View(h);tint.setBackgroundColor(0x99071020);root.addView(tint,new FrameLayout.LayoutParams(-1,-1));LinearLayout col=new LinearLayout(h);col.setOrientation(1);col.setPadding((int)h.dp(20),(int)h.dp(38),(int)h.dp(20),0);root.addView(col,new FrameLayout.LayoutParams(-1,-1));TextView title=h.caption("Библиотека",32,Color.WHITE);col.addView(title);TextView count=h.caption("Загрузка приложений…",13,0x99e1eaff);count.setPadding(0,(int)h.dp(4),0,(int)h.dp(16));col.addView(count);EditText search=h.input();search.setSingleLine();search.setTextSize(16);search.setTextColor(Color.WHITE);search.setHintTextColor(0x99ffffff);search.setHint("Поиск приложений");search.setPadding((int)h.dp(18),0,(int)h.dp(18),0);search.setBackground(h.surface(0x22e4f4ff,0x0cf0f8ff,23,0x30e6f6ff));LinearLayout.LayoutParams input=new LinearLayout.LayoutParams(-1,(int)h.dp(48));input.bottomMargin=(int)h.dp(18);col.addView(search,input);
 Grid grid=new Grid();h.libraryGrid=grid;grid.setNumColumns(4);grid.setStretchMode(GridView.STRETCH_COLUMN_WIDTH);grid.setVerticalScrollBarEnabled(false);grid.setSelector(android.R.color.transparent);grid.setClipToPadding(false);grid.setPadding(0,0,0,(h.screen==null?0:h.screen.bottomInset)+(int)h.dp(14));col.addView(grid,new LinearLayout.LayoutParams(-1,0,1));Adapter adapter=new Adapter(root);grid.setAdapter(adapter);Runnable filter=()->{if(!h.drawer||h.libraryGrid!=grid)return;String query=search.getText().toString().trim().toLowerCase(Locale.ROOT);adapter.filtered.clear();for(Item item:items)if(item.search.contains(query))adapter.filtered.add(item);count.setText(items.size()+" приложений");adapter.notifyDataSetChanged();};search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void onTextChanged(CharSequence s,int a,int b,int c){h.handler.removeCallbacks(filter);h.handler.postDelayed(filter,100);}public void afterTextChanged(Editable e){}});root.setFocusableInTouchMode(true);root.requestFocus();h.setContentView(root);root.setAlpha(.35f);root.setTranslationY(h.dp(35));root.animate().alpha(1).translationY(0).setDuration(240).start();loadAsync(filter);}
 final class Adapter extends BaseAdapter{final ArrayList<Item> filtered=new ArrayList<>();final FrameLayout root;Adapter(FrameLayout root){this.root=root;}public int getCount(){return filtered.size();}public Object getItem(int position){return filtered.get(position);}public long getItemId(int position){return position;}public View getView(int position,View recycled,ViewGroup parent){Tile tile=recycled instanceof Tile?(Tile)recycled:new Tile();tile.bind(filtered.get(position),root);return tile;}}
 final class Tile extends View{final Paint paint=new Paint(3);Item item;String key;Bitmap icon;Tile(){super(home);setLayoutParams(new AbsListView.LayoutParams(-1,(int)home.dp(106)));setFocusable(true);}void bind(Item next,FrameLayout root){item=next;key=imageKey(next);icon=images.get(key);setContentDescription(next.name);setOnClickListener(v->home.launch(next.app.activityInfo.packageName));setOnLongClickListener(v->{home.dragFromLibrary(this,root,next.app);return true;});if(icon==null){final String requested=key;request(next,key,()->{if(requested.equals(key)){icon=images.get(requested);invalidate();}});}invalidate();}protected void onDraw(Canvas canvas){if(item==null)return;float side=home.dp(57),x=getWidth()/2f;RectF rect=new RectF(x-side/2,home.dp(9),x+side/2,home.dp(9)+side);paint.setShader(null);paint.setColor(0x22ffffff);if(icon==null)canvas.drawRoundRect(rect,home.dp(18),home.dp(18),paint);else canvas.drawBitmap(icon,null,rect,paint);paint.setColor(0xf0ffffff);paint.setTextAlign(Paint.Align.CENTER);paint.setTypeface(home.uiFont(400));paint.setTextSize(home.dp(10.5f));String label=TextUtils.ellipsize(item.name,new android.text.TextPaint(paint),getWidth()-home.dp(5),TextUtils.TruncateAt.END).toString();canvas.drawText(label,x,home.dp(86),paint);}}
 final class Grid extends GridView{final Paint fade=new Paint(3);int oldHeight;Grid(){super(home);}protected void dispatchDraw(Canvas canvas){super.dispatchDraw(canvas);int bottom=getHeight(),band=(home.screen==null?0:home.screen.bottomInset)+(int)home.dp(40);if(oldHeight!=bottom){oldHeight=bottom;fade.setShader(new LinearGradient(0,bottom-band,0,bottom,new int[]{0x0009162b,0x6609162b},null,Shader.TileMode.CLAMP));}canvas.drawRect(0,bottom-band,getWidth(),bottom,fade);}}
}
